import { randomUUID } from 'node:crypto'
import type { NextFunction, Request, Response } from 'express'
import type { ApiRequest } from './request-context'

/**
 * EXI-PLAT-05 / Q-PLAT-02: `X-Request-Id` on every response, a UUID generated by the server (a client-supplied
 * value is ignored); it appears in every technical log line and in no response body.
 */
export function requestIdMiddleware(req: Request, res: Response, next: NextFunction): void {
  const id = randomUUID()
  ;(req as ApiRequest).id = id
  res.setHeader('X-Request-Id', id)
  const started = process.hrtime.bigint()
  if (process.env.JEST_WORKER_ID) return next() // in-process test servers stay quiet
  res.on('finish', () => {
    const ms = Number((process.hrtime.bigint() - started) / 1_000_000n)
    // the path only: a query string may carry filters, never logged
    process.stdout.write(
      `${JSON.stringify({ level: 'info', requestId: id, method: req.method, path: req.path, status: res.statusCode, ms })}\n`,
    )
  })
  next()
}
